PRAGMA synchronous = OFF;
PRAGMA journal_mode = MEMORY;
BEGIN TRANSACTION;
CREATE TABLE `alembic_version` (
  `version_num` varchar(32) NOT NULL
,  PRIMARY KEY (`version_num`)
);
INSERT INTO `alembic_version` VALUES ('264110f95dd8');
CREATE TABLE `beds` (
  `id` integer NOT NULL PRIMARY KEY AUTOINCREMENT
,  `room_id` integer NOT NULL
,  `bed_number` varchar(50) NOT NULL
,  `bed_name` varchar(100) DEFAULT NULL
,  `status` varchar(20) DEFAULT NULL
,  `camera_id` integer DEFAULT NULL
,  `created_at` datetime DEFAULT NULL
,  `intercom_ip` varchar(50) DEFAULT NULL
,  CONSTRAINT `beds_ibfk_1` FOREIGN KEY (`room_id`) REFERENCES `rooms` (`id`) ON DELETE CASCADE
,  CONSTRAINT `beds_ibfk_2` FOREIGN KEY (`camera_id`) REFERENCES `cameras` (`id`) ON DELETE SET NULL
);
