CREATE TABLE `events` (
  `id` integer NOT NULL PRIMARY KEY AUTOINCREMENT
,  `bed_id` integer DEFAULT NULL
,  `call_session_id` integer DEFAULT NULL
,  `device_timestamp` varchar(50) DEFAULT NULL
,  `system_timestamp` datetime NOT NULL
,  `room_identifier` varchar(200) DEFAULT NULL
,  `device_type` varchar(100) DEFAULT NULL
,  `event_type` varchar(50) NOT NULL
,  `status` varchar(20) DEFAULT NULL
,  `acknowledged_at` datetime DEFAULT NULL
,  `cleared_at` datetime DEFAULT NULL
,  `raw_hex` text DEFAULT NULL
,  `created_at` datetime DEFAULT NULL
,  `room_id` integer DEFAULT NULL
,  CONSTRAINT `events_ibfk_1` FOREIGN KEY (`bed_id`) REFERENCES `beds` (`id`) ON DELETE CASCADE
,  CONSTRAINT `events_ibfk_2` FOREIGN KEY (`call_session_id`) REFERENCES `call_sessions` (`id`) ON DELETE SET NULL
,  CONSTRAINT `fk_events_room_id_rooms` FOREIGN KEY (`room_id`) REFERENCES `rooms` (`id`) ON DELETE SET NULL
);
